"""Static game data bundled with the CLI (generated by tools/build_data.py)."""
import json
import re
from functools import lru_cache
from pathlib import Path

DATA_DIR = Path(__file__).resolve().parent / "data"


# Global-parameter maximums. Amazonis Planitia has longer tracks (upstream src/common/constants.ts).
STANDARD_MAX = {"temperature": 8, "oxygen": 14, "oceans": 9, "venus": 30}
AMAZONIS_MAX = {"temperature": 14, "oxygen": 18, "oceans": 11, "venus": 33}
PARAM_STEP = {"temperature": 2, "oxygen": 1, "oceans": 1, "venus": 2}


def is_amazonis(game):
    return str((game.get("gameOptions") or {}).get("boardName", "")).lower() == "amazonis planitia"


def param_max(game):
    """The four global parameters' maximums for this game's map."""
    return AMAZONIS_MAX if is_amazonis(game) else STANDARD_MAX


def steps_left(game):
    """Raises left on each global parameter (a final partial Venus step still counts as one)."""
    top = param_max(game)
    now = {"temperature": game.get("temperature", -30), "oxygen": game.get("oxygenLevel", 0),
           "oceans": game.get("oceans", 0), "venus": game.get("venusScaleLevel", 0) or 0}
    return {p: max(0, -(-(top[p] - now[p]) // PARAM_STEP[p])) for p in top}


def track_bonuses(game):
    """Bonuses printed on the temperature, oxygen and Venus tracks: {param: [(threshold, bonus), ...]}
    (upstream src/server/boards/GlobalParameterTracks.ts)."""
    if is_amazonis(game):
        return {"temperature": [(-24, "heatproduction"), (-20, "heatproduction"), (-12, "plantproduction"), (0, "ocean")],
                "oxygen": [(7, "drawcard"), (11, "temperature")],
                "venus": [(8, "drawcard"), (16, "colony"), (22, "tr")]}
    return {"temperature": [(-24, "heatproduction"), (-20, "heatproduction"), (0, "ocean")],
            "oxygen": [(8, "temperature")],
            "venus": [(8, "drawcard"), (16, "tr")]}


@lru_cache(maxsize=None)
def _load(name):
    return json.loads((DATA_DIR / name).read_text(encoding="utf-8"))


def cards():
    return _load("cards.json")


def card_name(name):
    """Canonical card name, matching case-insensitively and ignoring variant suffixes like ':u'."""
    db = cards()
    if name in db:
        return name
    lower = name.lower()
    for key in db:
        if key.lower() == lower or key.split(":")[0].lower() == lower:
            return key
    return None


def card(name):
    key = card_name(name)
    return cards()[key] if key else None


# Icon glyphs the card renderer exports as words ("-X 2x Action: ...", "2x bonus Place a colony"), at the start of
# the text or of a sentence.
_GLYPHS = re.compile(r"(^|(?<=[.)] ))(?:(?:-?[xX]|\d+x|\+\d*|bonus)\s+)+(?=[A-Z(])")


def card_text(name):
    """A card's text without the renderer's icon glyphs."""
    info = card(name) or {}
    return _GLYPHS.sub(r"\1", info.get("text") or "").strip()


def behavior(name):
    """Declarative effects of a card (behavior, action, VP rule...), exported from the app."""
    key = card_name(name)
    return _load("behaviors.json")["cards"].get(key) if key else None


def planetary_tracks():
    """Pathfinders planetary tracks: per track, a list of spaces with risingPlayer/everyone/mostTags rewards."""
    return {k: v["spaces"] for k, v in _load("behaviors.json")["planetaryTracks"].items()}


def milestone_text(name):
    return _load("ma.json")["milestones"].get(name)


def award_text(name):
    return _load("ma.json")["awards"].get(name)


def colony(name):
    return _load("colonies.json").get(name)


def board():
    return _load("board.json")


def adjacency(board_name, space_id):
    return board()["boards"].get(board_name, {}).get(space_id, {}).get("adj", [])


def tile_name(tile_type):
    return board()["tileType"].get(str(tile_type), f"tile{tile_type}")


def bonus_name(bonus):
    return board()["spaceBonus"].get(str(bonus), f"bonus{bonus}").lstrip("_")
